import{_ as s,o as n,c as e,aO as p}from"./chunks/framework.vjUPZZJn.js";const u=JSON.parse('{"title":"AI 技术调研方法：迭代流程、可核实性与提示词模板","description":"","frontmatter":{"date":"2026-11-06T10:00:00.000Z","title":"AI 技术调研方法：迭代流程、可核实性与提示词模板","source":[["1-知识/AI 应用/AI技术调研方法"]],"tags":["AI应用","提示词","方法论","学习笔记"],"categories":["AI 应用"],"permalink":"/pages/9fb12c"},"headers":[],"relativePath":"AI 应用/AI 技术调研方法：迭代流程、可核实性与提示词模板.md","filePath":"AI 应用/AI 技术调研方法：迭代流程、可核实性与提示词模板.md","lastUpdated":1793954909000}'),l={name:"AI 应用/AI 技术调研方法：迭代流程、可核实性与提示词模板.md"};function i(r,a,t,o,c,b){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="ai-技术调研方法-迭代流程、可核实性与提示词模板" tabindex="-1">AI 技术调研方法：迭代流程、可核实性与提示词模板 <a class="header-anchor" href="#ai-技术调研方法-迭代流程、可核实性与提示词模板" aria-label="Permalink to &quot;AI 技术调研方法：迭代流程、可核实性与提示词模板&quot;">​</a></h1> <p>用 AI 做技术调研，常见的结果是：拿到一篇面面俱到却读不进去的长文，结论看起来合理，但不知道哪些可信。这篇文章写给需要用 AI 完成选型、对比、方案评估的开发者，给出一套可操作的调研流程：如何拆分提问、如何要求可核实的输出、如何用提示词模板把这些约束固化下来。读完可以直接套用文末的模板开展下一次调研。</p> <h2 id="为什么-ai-调研结果总不满意" tabindex="-1">为什么 AI 调研结果总不满意 <a class="header-anchor" href="#为什么-ai-调研结果总不满意" aria-label="Permalink to &quot;为什么 AI 调研结果总不满意&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>问题</th> <th>根因</th></tr></thead> <tbody><tr><td>内容太多，阅读困难</td> <td>没有限定输出格式，AI 默认「全面 = 好」</td></tr> <tr><td>缺少核实列表</td> <td>AI 倾向给结论而非证据链</td></tr> <tr><td>主观 / 翻译腔 / 黑话</td> <td>模型训练数据偏英文，翻译式输出是常态</td></tr> <tr><td>质量不高</td> <td>一次提问想解决所有问题，粒度太粗</td></tr></tbody></table> <p>核心认知：<strong>AI 调研不是一次对话，是一个迭代流程</strong>。一次提问要 AI 同时完成搜索、筛选、分析、写作，每一步的质量都会被压缩。拆开之后，中间的决策点由自己控制，结果才可控。</p> <blockquote><p>AI 调研 = AI 找框架 + AI 找资料 + 自己读原文 + AI 整理对比。
不要让 AI 替你下结论，让它替你省掉「找」和「整理」的时间。</p></blockquote> <h2 id="调研流程" tabindex="-1">调研流程 <a class="header-anchor" href="#调研流程" aria-label="Permalink to &quot;调研流程&quot;">​</a></h2> <h3 id="第-0-步-先定框架-再填内容" tabindex="-1">第 0 步：先定框架，再填内容 <a class="header-anchor" href="#第-0-步-先定框架-再填内容" aria-label="Permalink to &quot;第 0 步：先定框架，再填内容&quot;">​</a></h3> <p>调研失败大半败在问题没定义清楚。直接问「帮我调研 X」，得到的就是泛泛而谈的大杂烩。</p> <p>两种做法：</p> <p><strong>让 AI 先反问再答</strong>：</p> <blockquote><p>我要调研 XXX。在开始之前，先问我 3 个问题来明确我的需求，然后按我的回答输出。</p></blockquote> <p><strong>对比型调研直接给框架</strong>。错误问法：</p> <blockquote><p>帮我调研 Kubernetes 网络方案</p></blockquote> <p>正确问法：</p> <blockquote><p>我要对比 Kubernetes 的 3 种主流网络方案（Calico / Flannel / Cilium），维度是：性能开销、网络策略能力、生产案例。先给我一个对比框架（表格），每个维度只列关键结论，不要展开。</p></blockquote> <p>原则：先骨架后血肉，先表格后段落。</p> <h3 id="第-1-步-广度扫描-只要清单" tabindex="-1">第 1 步：广度扫描，只要清单 <a class="header-anchor" href="#第-1-步-广度扫描-只要清单" aria-label="Permalink to &quot;第 1 步：广度扫描，只要清单&quot;">​</a></h3> <p>明确禁止 AI 写长文，只要结构化的候选列表：</p> <blockquote><p>请列出与___相关的主要方案 / 工具 / 技术路线。每个只给三行：名称、一句话说明它是什么、官方文档链接。不要展开分析，不要给推荐，不要写优缺点对比。</p></blockquote> <p>拿到清单后由自己决定往哪个方向深挖。AI 没有你的项目上下文和取舍标准，这一步不能外包。</p> <h3 id="第-2-步-逐项深挖-每次只问一个维度" tabindex="-1">第 2 步：逐项深挖，每次只问一个维度 <a class="header-anchor" href="#第-2-步-逐项深挖-每次只问一个维度" aria-label="Permalink to &quot;第 2 步：逐项深挖，每次只问一个维度&quot;">​</a></h3> <p>一次只对比两三个候选，一次只问一个维度（性能？许可证？维护活跃度？迁移成本？）：</p> <blockquote><p>关于 Cilium 的性能开销，给我具体数据：延迟增加多少、吞吐量影响、资源消耗。附带来源链接。
Cilium 在生产环境的案例，给我 3 个真实公司的落地经验，附链接。</p></blockquote> <h3 id="第-3-步-汇总成文-结论自己定" tabindex="-1">第 3 步：汇总成文，结论自己定 <a class="header-anchor" href="#第-3-步-汇总成文-结论自己定" aria-label="Permalink to &quot;第 3 步：汇总成文，结论自己定&quot;">​</a></h3> <p>把零散笔记交给 AI 按模板整理，而不是让它自己「总结出结论」。AI 自己总结的结论往往是最不可靠的部分，却最容易写得冠冕堂皇。</p> <p>AI 可以给倾向性判断，但要求它同时给出支持和反对的理由。它的推荐经常是「四平八稳选最流行的那个」，未必贴合你的约束，最终拍板留给自己。</p> <h2 id="可核实性" tabindex="-1">可核实性 <a class="header-anchor" href="#可核实性" aria-label="Permalink to &quot;可核实性&quot;">​</a></h2> <h3 id="前提-用带联网检索的-ai" tabindex="-1">前提：用带联网检索的 AI <a class="header-anchor" href="#前提-用带联网检索的-ai" aria-label="Permalink to &quot;前提：用带联网检索的 AI&quot;">​</a></h3> <p>纯靠模型记忆回答时，版本号、API、许可证状态经常过时甚至编造。更要紧的是，AI 编造链接时并不觉得自己在编造——它输出的是一个「看起来应该存在」的 URL，提示词里写「不要编造链接」挡不住。</p> <p>所以「可核实」成立的前提只有两个：</p> <ol><li>用带真实联网检索能力的 AI（能引用实时搜索结果）；</li> <li>自己点开链接抽查，验证是否真的支持那条结论。</li></ol> <p>优先信官方文档、issue、changelog，其次是技术博客，最不可信的是 AI 推理出来的「应该可以」。</p> <h3 id="每次提问都带的标注约束" tabindex="-1">每次提问都带的标注约束 <a class="header-anchor" href="#每次提问都带的标注约束" aria-label="Permalink to &quot;每次提问都带的标注约束&quot;">​</a></h3> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输出要求：</span></span>
<span class="line"><span>1. 每个关键结论必须附带来源链接或官方文档地址</span></span>
<span class="line"><span>2. 无法核实的标注 [未验证]</span></span>
<span class="line"><span>3. 不确定的标注 [存疑]</span></span>
<span class="line"><span>4. 不要编造链接</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>标注体系建立在上一步的真实检索之上；来源本身可能是假的时，标注就建立在流沙上。</p> <h3 id="钉死版本和日期" tabindex="-1">钉死版本和日期 <a class="header-anchor" href="#钉死版本和日期" aria-label="Permalink to &quot;钉死版本和日期&quot;">​</a></h3> <p>提问时写明「以 2026 年 8 月的最新稳定版为准」。不写这句，AI 可能拿两三年前的状态回答——许可证变更、API 废弃、性能数据，这些都是调研里的高危过期信息。</p> <h2 id="语言约束" tabindex="-1">语言约束 <a class="header-anchor" href="#语言约束" aria-label="Permalink to &quot;语言约束&quot;">​</a></h2> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语言要求：</span></span>
<span class="line"><span>1. 用中文工程师日常交流的口吻，不要翻译腔</span></span>
<span class="line"><span>2. 术语保留英文原文，不要硬翻（如：不要把 eBPF 翻成「扩展伯克利包过滤器」）</span></span>
<span class="line"><span>3. 避免空洞的形容词（「强大的」「优秀的」），用数据替代</span></span>
<span class="line"><span>4. 如果一句话去掉不影响理解，就删掉</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>更有效的做法是给 AI 两三段自己写的文字作为文风样例，要求模仿这个文风。</p> <h2 id="prompt-模板" tabindex="-1">Prompt 模板 <a class="header-anchor" href="#prompt-模板" aria-label="Permalink to &quot;Prompt 模板&quot;">​</a></h2> <p>把上面的约束固化成模板，每次调研直接套：</p> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## 调研任务</span></span>
<span class="line"><span>[一句话描述要调研什么，解决什么问题]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 调研类型</span></span>
<span class="line"><span>- 对比型（选 A 还是 B）：走表格框架</span></span>
<span class="line"><span>- 单点型（X 能否解决 Y / X 的某机制）：直接问答</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 调研范围</span></span>
<span class="line"><span>- 对比对象：A / B / C（单点型可省）</span></span>
<span class="line"><span>- 关注维度：[列出 2-4 个]</span></span>
<span class="line"><span>- 版本基准：以 YYYY 年 M 月的最新稳定版为准</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 输出格式</span></span>
<span class="line"><span>1. 对比型先给对比表格（维度 × 对象），每格一句话结论</span></span>
<span class="line"><span>2. 再对每个维度展开，每段不超过 200 字</span></span>
<span class="line"><span>3. 最后给倾向性判断 + 支持理由 + 反对理由（最终决策我自己做）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 约束</span></span>
<span class="line"><span>- 每个关键结论附来源链接，无法核实标 [未验证]，不确定标 [存疑]</span></span>
<span class="line"><span>- 用中文工程师口吻，术语保留英文</span></span>
<span class="line"><span>- 空洞形容词用数据替代，删掉不影响理解的句子</span></span>
<span class="line"><span>- 有实质差异才写，没差异的维度不要凑数</span></span>
<span class="line"><span>- 总长度控制在 2000 字以内</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2> <ul><li><strong>警惕「完美对称的对比表」</strong>。AI 爱写每个格子都填满的优缺点表格，看起来工整，实际很多格子里是凑数的废话。要求它「没有实质差异的维度直接删掉」。</li> <li><strong>分角色验证价值有限</strong>。让同一个模型扮演反对者批判自己刚写的结论，它倾向于找几个无伤大雅的漏洞交差，盲点是共享的。要交叉验证，换一个不同的模型，或者直接对官方文档。</li> <li><strong>换问法重问是弱信号</strong>。同一个问题换个问法问两遍，矛盾的地方确实可能是幻觉，但也可能只是问法差异。它可以当线索，不能当证据，核实还是靠读原文。</li> <li><strong>AI 最适合的环节是找方向和找资料，不是替代阅读</strong>：</li></ul> <blockquote><p>给我 5 篇关于 Cilium 性能测试的技术博客，按质量排序，每篇用一句话说明重点。</p></blockquote> <p>然后自己读原文。</p> <h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2> <p>这套方法的核心只有一句话：把调研拆成「定框架 → 扫清单 → 逐维深挖 → 自己定结论」四步，AI 负责其中的查找与整理，人负责决策与核实。配合标注约束（来源链接、[未验证]、[存疑]）与版本钉死，AI 输出的可信度才有基本保障。模板可以直接复制使用，按项目实际情况增删维度即可。</p>`,96)])])}const h=s(l,[["render",i]]);export{u as __pageData,h as default};
